from base import *
import matplotlib.pyplot as plt
import zipfile,re,html,importlib.metadata
P=OUT/'04_niche_comparison';S=OUT/'05_source_validation';R=OUT/'reports';F=OUT/'06_figures'
def figsave(fig,name):
 fig.tight_layout();fig.savefig(F/(name+'.png'),transparent=True,dpi=150);fig.savefig(F/(name+'.pdf'),transparent=True);plt.close(fig)
def main():
 d=pd.read_parquet(P/'anchor_MP10_all_layers.parquet');a=d[d.accepted_label.ge(0)];b=pd.read_csv(P/'unit_bootstrap_effects.tsv',sep='\t');summ=pd.read_csv(P/'niche_MP10_summary_all9.tsv',sep='\t');sh=pd.read_csv(P/'signature_counts_attribution.tsv',sep='\t');sim=pd.read_csv(S/'composition_only_pseudospots.tsv',sep='\t');st=pd.read_csv(S/'state_control_paired_effects.tsv',sep='\t');blue=pd.read_csv(S/'central_composition_blueprints.tsv',sep='\t');manifest=pd.read_csv(OUT/'03_epi_attribution/model_and_gene_universe_manifest.tsv',sep='\t');sv=json.loads((S/'source_validation_manifest.json').read_text())
 # Exact same selected real centers for descriptive simulated-vs-real contrasts.
 actual=d.set_index('spot_uid');sim['actual_observed']=sim.blueprint_uid.map(actual.spot_MP10_model_universe);sim['actual_epi']=sim.blueprint_uid.map(actual.epi_MP10_model_universe);comp=[]
 for dataset,g in sim.groupby('dataset_id'):
  for n in range(9):
   ng=g[g.niche_name.eq(f'niche{n}')];rest=g[g.niche_name.ne(f'niche{n}')]
   comp.append(dict(dataset_id=dataset,niche_name=f'niche{n}',n_blueprints=ng.blueprint_uid.nunique(),n_rest_blueprints=rest.blueprint_uid.nunique(),composition_only_effect=ng.observed_score.median()-rest.observed_score.median(),actual_same_blueprints_effect=ng.actual_observed.median()-rest.actual_observed.median(),actual_same_blueprints_epi_effect=ng.actual_epi.median()-rest.actual_epi.median(),scope='dataset-relative descriptive blueprints; not independent-patient effect'))
 tab(S/'composition_same_blueprint_effects.tsv',comp);cp=pd.DataFrame(comp);rows=[]
 for n in range(9):
  name=f'niche{n}';g=a[a.niche_name.eq(name)];bb=b[b.niche_name.eq(name)&b.analysis_set.eq('MATCHED_FULL20_EPI')];ob=bb[bb.score.eq('spot_MP10_model_universe')];ep=bb[bb.score.eq('epi_MP10_model_universe')];ov=ob.mean_effect.iloc[0] if len(ob) else np.nan;ev=ep.mean_effect.iloc[0] if len(ep) else np.nan;nu=int(ep.n_units.iloc[0]) if len(ep) else 0;cc=cp[cp.niche_name.eq(name)].dropna(subset=['composition_only_effect','actual_same_blueprints_effect']);same=(np.sign(cc.composition_only_effect)==np.sign(cc.actual_same_blueprints_effect)).mean() if len(cc) else np.nan;state=st[st.niche_name.eq(name)];level='UNRESOLVED';reason='Unit interval crosses zero or control evidence does not resolve source.'
  if nu>=5 and np.isfinite(ov) and np.isfinite(ev):
   if ov*ev<0:level='DISCORDANT';reason='Opposite mean within-unit directions on identical centers and gene backgrounds.'
   elif abs(ev)<abs(ov) or same>=.5:level='COMPOSITION_CONFOUNDED_OR_ATTENUATED';reason='Effect attenuates after model attribution and/or composition-only controls reproduce direction; not a fraction of explained score.'
   elif len(ep) and ep.ci_low.iloc[0]*ep.ci_high.iloc[0]>0 and len(ob) and ob.ci_low.iloc[0]*ob.ci_high.iloc[0]>0:level='MODEL_ASSISTED_EPI_SUPPORT';reason='Paired effect persists; limited composition control does not reproduce majority of dataset directions. Model-assisted, not independent specificity proof.'
  if len(ep) and ep.ci_low.iloc[0]<=0<=ep.ci_high.iloc[0]:
   if len(ob) and ob.ci_low.iloc[0]*ob.ci_high.iloc[0]>0 and abs(ev)<abs(ov):level='COMPOSITION_CONFOUNDED_OR_ATTENUATED';reason='Observed within-unit effect attenuates in model Epi; Epi interval includes zero. Composition and model uncertainty remain; not proof of explained source.'
   else:level='UNRESOLVED';reason='Exploratory Epi unit interval includes zero; point-estimate direction alone does not resolve source.'
  s1=summ[(summ.analysis_set=='FULL20_SPOT_PRIMARY')&(summ.niche_name==name)&(summ.score=='spot_MP10_frozen')];s2=summ[(summ.analysis_set=='MATCHED_FULL20_EPI')&(summ.niche_name==name)&(summ.score=='epi_MP10_model_universe')];share=sh[sh.niche_name.eq(name)];rows.append(dict(niche_name=name,n_accepted=len(g),n_frozen_full20=int(s1.n.iloc[0]),spot_MP10_median=s1['median'].iloc[0],epi_MP10_matched_median=s2['median'].iloc[0],n_matched=int(s2.n.iloc[0]),spot_within_unit_effect=ov,epi_within_unit_effect=ev,n_independent_units=nu,epi_ci_low=ep.ci_low.iloc[0] if len(ep) else np.nan,epi_ci_high=ep.ci_high.iloc[0] if len(ep) else np.nan,n_partial_signature=int(g.n_signature_available_model.lt(20).sum()),matched_universe_status='same centers, same per-section ordered broad model genes',signature_epi_count_share_median=share.signature_epi_count_share_of_observed.iloc[0],single_cell_support=f"{sv['n_sc']} real scRNA cells, 30 mapped types; {sv['n_usage_matched']} Epi usage matches; no spatial patient pairing",composition_only_result=f'{len(cc)} datasets; direction reproduced fraction={same:.3f}',state_change_control_result=f'{len(state)} paired blueprints; median observed high-low={state.observed_high_minus_low.median():.5f}; true Epi high-low={state.true_epi_high_minus_low.median():.5f}',high_epi_sensitivity='see coverage_sensitivity.tsv and unit_bootstrap_effects.tsv; same frozen labels',pathology_scope='unknown; 0 accepted regional author/user labels',source_evidence_level=level,unresolved_reason=reason))
 evidence=pd.DataFrame(rows);cv=pd.read_csv(P/'coverage_sensitivity.tsv',sep='\t')
 for subset,tag in [('EPI_GE_0.5','epi05'),('EPI_GE_0.7','epi07')]:
  counts=cv[cv.analysis_set.eq(subset)].set_index('niche_name')['n'];ef=b[b.analysis_set.eq(subset)&b.score.eq('epi_MP10_model_universe')].set_index('niche_name').mean_effect;evidence[tag+'_n']=evidence.niche_name.map(counts);evidence[tag+'_unit_effect']=evidence.niche_name.map(ef)
 tab(S/'source_evidence_all9.tsv',evidence)
 fig,axes=plt.subplots(3,3,figsize=(13,10),sharey=True)
 for n,ax in enumerate(axes.ravel()):
  for score,color,offset in [('spot_MP10_model_universe','tab:blue',-.12),('epi_MP10_model_universe','tab:orange',.12)]:
   unit=pd.read_csv(P/'independent_unit_effects.tsv',sep='\t');g=unit[unit.analysis_set.eq('MATCHED_FULL20_EPI')&unit.score.eq(score)&unit.niche_name.eq(f'niche{n}')];ax.scatter(np.arange(len(g))+offset,g.effect,s=10,color=color,alpha=.6,label=score.split('_')[0]);ax.axhline(0,c='gray',lw=.7)
  ax.set_title(f'niche{n}');ax.set_xlabel('independent units (patient sections bundled)');ax.set_ylabel('within-section effect')
 axes[0,0].legend();figsave(fig,'independent_unit_effects_all9')
 fig,axes=plt.subplots(1,2,figsize=(12,5))
 for n in range(9):
  ss=sim[sim.niche_name.eq(f'niche{n}')];axes[0].boxplot([ss.observed_score.to_numpy()],positions=[n],showfliers=False);ss=st[st.niche_name.eq(f'niche{n}')];axes[1].scatter(np.repeat(n,len(ss)),ss.observed_high_minus_low,alpha=.4,s=10)
 for ax in axes:ax.set_xticks(range(9),[f'n{i}' for i in range(9)])
 axes[0].set_title('Composition-only, identical Epi donor distribution');axes[1].set_title('Fixed composition/depth, Epi high minus low state');axes[1].axhline(0,c='gray');figsave(fig,'source_controls_all9')
 cov=pd.read_csv(P/'coverage_sensitivity.tsv',sep='\t');h=cov.pivot(index='analysis_set',columns='niche_name',values='n');fig,ax=plt.subplots(figsize=(12,6));im=ax.imshow(np.log1p(h),aspect='auto',cmap='viridis');ax.set_xticks(range(9),h.columns);ax.set_yticks(range(len(h)),h.index);fig.colorbar(im,label='log(1+anchors)');figsave(fig,'coverage_sensitivity')
 # Spatial displays retain zeros black and NA gray, separate score scales.
 spatial=F/'spatial';spatial.mkdir(exist_ok=True)
 for sec,g in d.groupby('section_id'):
  fig,axes=plt.subplots(1,3,figsize=(12,4));
  for ax,col in zip(axes,['spot_MP10_frozen','spot_MP10_model_universe','epi_MP10_model_universe']):
   v=g[col];na=v.isna();zero=v.eq(0);pos=v.gt(0);ax.scatter(g.loc[na,'x'],g.loc[na,'y'],s=2,c='lightgray');ax.scatter(g.loc[zero,'x'],g.loc[zero,'y'],s=2,c='black');im=ax.scatter(g.loc[pos,'x'],g.loc[pos,'y'],c=v[pos],s=2,cmap='plasma',vmin=0,vmax=max(.01,v.max()) if v.notna().any() else 1);fig.colorbar(im,ax=ax,shrink=.6);ax.set_title(col,fontsize=7);ax.set_aspect('equal');ax.invert_yaxis();ax.axis('off')
  fig.suptitle(sec+' | zero=black; NA=gray | all common anchors');fig.tight_layout();fig.savefig(spatial/(sec+'.png'),dpi=120,transparent=True);fig.savefig(spatial/(sec+'.pdf'),transparent=True);plt.close(fig)
 # Frozen labels and source files remain unchanged.
 hashes=pd.read_csv(OUT/'00_audit_and_freeze/niche_input_hashes.tsv',sep='\t');hashes['sha256_after']=hashes.path.map(sha);assert hashes.sha256.eq(hashes.sha256_after).all();tab(OUT/'00_audit_and_freeze/frozen_input_integrity_final.tsv',hashes)
 repro=pd.read_csv(OUT/'02_spot_MP10/frozen_reproduction.tsv',sep='\t');tech=pd.read_csv(OUT/'03_epi_attribution/attribution_technical_validation.tsv',sep='\t');assert tech.status.eq('PASS').all();assert len(d)==129632 and d.spot_uid.is_unique;assert not manifest.status.isin(['PENDING','FAILED']).any();assert d.loc[d.n_signature_available_model.lt(20),'epi_MP10_model_universe'].isna().all()
 # Expand source inventory fields and give all public/local records concrete evidence links.
 invpath=OUT/'01_pathology_search/pathology_source_inventory.tsv';inv=pd.read_csv(invpath,sep='\t');logs=pd.read_csv(OUT/'01_pathology_search/public_and_local_search_log.tsv',sep='\t');
 for c in ['accession','title','url','annotation_format','image_resolution','applicable_region','author','date']:
  if c not in inv:inv[c]='not established'
 public=[]
 for z in logs.to_dict('records'):
  public.append(dict(source_id=z.get('source_id'),url=z.get('url'),local_path=z.get('local_path'),evidence_status=z.get('status'),date='2026-10-13',limitation=z.get('reason','Public/local source searched; no joinable regional mask established'),annotation_level='source/code only',exact_mapping='see identity overlay and search log; no automatic spot mapping'))
 inv=pd.concat([inv,pd.DataFrame(public)],ignore_index=True).drop_duplicates('source_id',keep='last');tab(invpath,inv)
 (R/'METHODS.md').write_text('''# Methods and interpretation\n\nFrozen SAMPLE_R12_LEIDEN labels 0–8, q05 environment and c2l mean Epi gate are untouched. Formal labels exclude UNASSIGNED from niche summaries, while all common anchors remain in the full table. Patient identities use the accepted overlay; anonymous policy units are not relabeled as known patients.\n\nHistorical Top20 AUCell is the recovered Python average-tie rank implementation: raw counts, K=ceil(.05*G), sum(max(0,K-rank(signature)))/sum(K-r), r=1..min(signature size,K). It is not an assertion that the historical code exactly reproduces R AUCell random tie handling. Original frozen values are retained; predetermined first12 centers per section are reproduced.\n\nFor saved joint posterior means, conditional Epi counts=observed counts*(w_Epi*reference_Epi*m_g)/(w@reference.T*m_g+batch ambient). Detection cancels in the ratio. This is a plug-in attribution, not the posterior expectation of the attributed counts. No Epifraction multiplication or template-only expression was used. Full ordered model genes form the shared ranking background for observed/Epi scores. Fractional attributed counts are not rounded. Primary scores require all20 genes; B5 lacks HMGCS1 and is kept separately as partial sensitivity. Signature observed counts=0 yields NA count shares. All-zero Epi counts yield NA.\n\nThe installed official compute_expected_per_cell_type was compared at <=128 deterministic anchors per dataset, all30 types plus ambient reconstructing observed counts. Model restore was actually attempted successfully; scvi's Pyro on_load internally invokes one initialization step before loading saved state. This did not overwrite saved models or run full training. Subsequent validation uses the installed official function with exact saved reference/registry access to avoid repeated loader initialization. Full execution reads saved posterior means only.\n\nSection-niche versus rest median differences use at least20 anchors in both groups. Rest composition varies across sections. Sections of the same accepted patient/unit are bundled by averaging their section effects; >=5 units permit exploratory1000-resample unit bootstrap intervals. No iid spot P-values or SEs are reported. Intervals are exploratory, unadjusted across the nine contrasts and are not confirmatory tests. Source categories are conservative descriptive adjudications; when the Epi interval crosses zero, no MODEL_ASSISTED_EPI_SUPPORT is assigned. Attenuation means a smaller point effect with unresolved Epi interval, not a numerical fraction of source explained. A predefined section+niche+bs(Epi,df3)+log1p(nCount) regression provides descriptive coefficients only. Complete rings, Epi>=.5/.7, candidate labels, largest-dataset exclusion are sensitivity summaries, not new clustering or external validation.\n\nSource controls reuse9600 observed scRNA count profiles with verified32-to30 mapping; no independent malignant identities inferred. Existing fixed-W NNLS original EpiMP usage is reused where exact cell ids match. Composition-only blueprints use actual central mean30 cell proportions, each donor's unnormalized model-gene counts (retaining library-size differences), and exact observed central library depth within the same model-gene background. The same Epi donor set per repeat applies across all niches; other cell types change with actual composition. Five repeats are technical simulations, not patients. State controls keep non-Epi realized counts and total depth fixed; only the Epi profile changes. True Epi counts are saved. This does not validate abundance estimation end-to-end.\n\nNo saved matched joint posterior draws were found; draw-level uncertainty was not estimated. Independent q05 margins were never combined as a draw.\n\nSources: [cell2location official implementation](https://cell2location.readthedocs.io/en/latest/_modules/cell2location/models/_cell2location_module.html), [AUCell vignette](https://bioconductor.org/packages/release/bioc/vignettes/AUCell/inst/doc/AUCell.html), local installed source and frozen historical scoring script (see audits). Min20/min5/bootstrap1000 are project working rules, not universal statistical standards.\n''')
 limits='''# Remaining uncertainty\n\n- No traceable spot-level author/user pathology labels were established. GSE238145 tissue is specimen identity; GSE285715 N/T is tissue source, not a regional malignant/normal verdict. GSE319536 author code shows annotation variables but does not distribute the referenced annotation-bearing RDS/table. CanDis/NPJ alias crosswalks remain unresolved.\n- Model-attributed Epi is model support, not purified measured Epi and not proof of epithelial specificity or malignancy. No causal conclusion.\n- No paired posterior-draw uncertainty; point estimates only. Template/information diagnostics are provided.\n- B5 lacks HMGCS1; its19-gene results are descriptive only. Two sections have no common anchors, not failed model extraction.\n- Anonymous units have policy-based independence but not verified patient identities. Intervals are exploratory, and raw scores across different gene backgrounds are not a unique biological ranking.\n- scRNA is unpaired to spatial patients; projected usage and pseudo-spots are supporting technical checks. No oracle/end-to-end attribution validation, no newly estimated normal/malignant scRNA identities.\n'''
 (R/'WHAT_IS_STILL_UNCERTAIN.md').write_text(limits)
 complete=int(d.epi_score_valid.sum());accepted=int(d.accepted_label.ge(0).sum());lines=['# 本轮实际结果',f'固定九群；共同 anchors {len(d):,}，正式接受 {accepted:,}。中央冻结 MP10 覆盖 {d.section_id.nunique()} 张有共同 anchors 切片。完整20基因 matched Epi {complete:,} anchors；另有 B5 {int(d.n_signature_available_model.lt(20).sum())} 个19基因 anchors 单列。',f'七数据集技术 pilot 全部通过，Epi 最大绝对误差 {tech.official_epi_max_abs_error.max():.3g}；冻结分数复核 {len(repro)} 切片，最大差 {repro.max_abs_error.max():.3g}。',f"来源：{sv['n_sc']} 真实单细胞，{sv['n_blueprints']} 蓝本×5={sv['n_bags']} composition-only；{sv['n_state_blueprints']} 成对状态蓝本。",'病理检索覆盖7数据集/63切片；可直接应用的区域标签0，133 ROI 仍需复核。', '\n|niche|完整整体N|整体中位数|匹配Epi中位数|同中心整体效应|Epi效应|独立单位|来源级别|','|---|---:|---:|---:|---:|---:|---:|---|']
 for r in evidence.itertuples():lines.append(f'|{r.niche_name}|{r.n_frozen_full20}|{r.spot_MP10_median:.4f}|{r.epi_MP10_matched_median:.4f}|{r.spot_within_unit_effect:+.4f}|{r.epi_within_unit_effect:+.4f}|{r.n_independent_units}|{r.source_evidence_level}|')
 lines+=['\n整体列为原冻结背景，Epi列为模型背景，两者中位数不能直接相减。两效应列均来自同中心、同模型背景。','\n逐切片状态见 ../03_epi_attribution/model_and_gene_universe_manifest.tsv。无共同 anchors 的切片：'+', '.join(manifest.loc[manifest.status.eq('NO_COMMON_ANCHORS'),'section_id']), '\n入口：[双层图](../06_figures/ALL_DATASETS/matched_layers.png)、[来源证据](../05_source_validation/source_evidence_all9.tsv)、[病理复核](../01_pathology_search/user_review/review_index.html)、[限制](WHAT_IS_STILL_UNCERTAIN.md)。','\n续跑：bash code/resume_mp10_source_v4.sh（在本结果目录内；已完成阶段校验后跳过）。']
 (R/'RUN_SUMMARY.md').write_text('\n'.join(lines));(R/'REVIEW_INDEX.md').write_text('# 入口\n\n[实际结果](RUN_SUMMARY.md)\n\n[全部九群](../05_source_validation/source_evidence_all9.tsv)\n\n[病理复核 HTML](../01_pathology_search/user_review/review_index.html)\n\n[病理填写表](../01_pathology_search/user_review/ROI_review_to_fill.tsv)\n\n[方法](METHODS.md)\n\n[限制](WHAT_IS_STILL_UNCERTAIN.md)\n')
 js(OUT/'00_audit_and_freeze/completion_audit.json',dict(status='COMPLETED_WITH_EXPLICIT_LIMITATIONS',n_anchors=len(d),n_accepted=accepted,n_full20_epi=complete,n_sections=d.section_id.nunique(),n_niches=9,all_pilots_pass=True,immutable_inputs_unchanged=True,source_controls=sv,posterior_draws='not completed: no saved joint draws; optional limitation',pathology='unknown, 133 concrete review tasks'))
 # Light portable review: reports, tables, key plots and compressed previews, no models/count caches/full anchor table.
 zpath=R/'review.zip'
 with zipfile.ZipFile(zpath,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
  for p in OUT.rglob('*'):
   if not p.is_file() or p==zpath:continue
   rel=p.relative_to(OUT);parts=rel.parts
   include=False
   if parts[0]=='reports' and p.suffix=='.md':include=True
   elif parts[0]=='code' and p.suffix in ['.py','.sh']:include=True
   elif parts[0]=='00_audit_and_freeze' and p.suffix in ['.tsv','.json','.yaml']:include=True
   elif parts[0]=='01_pathology_search' and 'sources' not in parts and p.name!='spot_pathology_overlay.tsv':
    include=p.suffix in ['.tsv','.html','.md','.jpg','.json','.csv']
   elif parts[0] in ['02_spot_MP10','03_epi_attribution','04_niche_comparison','05_source_validation'] and 'by_section' not in parts and 'counts_cache' not in parts and p.suffix in ['.tsv','.json'] and p.stat().st_size<10e6 and p.name!='existing_EpiMP10_usage.tsv':include=True
   elif parts[0]=='06_figures' and 'spatial' not in parts and p.suffix in ['.png','.pdf']:include=True
   if include:z.write(p,str(rel))
 log(f'FINAL REVIEW PACKAGE {zpath} {zpath.stat().st_size/1e6:.1f} MB')
if __name__=='__main__':main()
